python -c "
import time, numpy as np, pandas as pd
from scipy.stats import spearmanr
from alphacrafter.sim.utils import get_stock_daily_data
WL=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in WL:
    df=get_stock_daily_data(symbol=s,days=4000)
    df=df.copy(); df['date']=pd.to_datetime(df['date']); df=df[df['date']<=pd.Timestamp('2026-07-15')].set_index('date')
    frames[s]=df['close'].astype(float)
idx=pd.DatetimeIndex(sorted(set().union(*[f.index for f in frames.values()])))
closes=pd.DataFrame({s:f.reindex(idx) for s,f in frames.items()})
def fwd_panel(h):
    out={}
    for a in WL:
        s=closes[a].dropna()
        out[a]= (s.shift(-h)/s-1.0).reindex(idx)
    return pd.DataFrame(out,index=idx)
FWD={h:fwd_panel(h) for h in (1,2,3,5,10,20)}
fp=pd.DataFrame({a:(closes[a].dropna().shift(5)/closes[a].dropna().shift(25)-1.0).reindex(idx) for a in WL},index=idx)
def ic_series(fp,h=10):
    fwd=FWD[h]
    out={}
    for t in fp.index:
        if t.dayofweek>=5: continue
        fv=fp.loc[t]; fr=fwd.loc[t].reindex(fv.index)
        m=fv.notna()&fr.notna()
        if int(m.sum())<8: continue
        ic,_=spearmanr(fv[m],fr[m])
        if np.isfinite(ic): out[t]=ic
    return pd.Series(out)
t0=time.time(); ic=ic_series(fp); print('one ic_series:', round(time.time()-t0,1),'s, n=',len(ic))
t0=time.time(); decay={str(h):float(ic_series(fp,h).mean()) for h in (1,2,3,5,10,20)}; print('decay 6 horizons:', round(time.time()-t0,1),'s')
"

